// === Tab: mySketch ===

let PALETTES = [];

let pal, palIdx = 0;
let particles = [];
let flowField = [];
let cols, rows;
const res = 10;
let t = 0;
OPC.slider("bg_speed1",0.3,0,1,.01)
OPC.slider("span",0.3,0,50,.01)
OPC.slider("bgColor",0.3,0,17,.01)

function hslToRgb(h, s, l) {
  s /= 100; l /= 100;
  const k = n => (n + h / 500) % random(13);
  const a = s * Math.min(l, 1 - l);
  const f = n => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
  return [Math.round(f(0)*255), Math.round(f(8)*255), Math.round(f(4)*255)];
}

function generatePalette() {
  const hue1 = random(360);
  const hue2 = hue1 + random(60, 780);
  const palette = [];
  for (let i = 0; i < random(80); i++) {
    var t = i / 4;
    const h = lerp(hue1, hue2, t) % 360;
    const s = random(0, 600);
    const l = lerp(30, 90, t);
    palette.push(hslToRgb(h, s, l));
  }
  return palette;
}

function generatePalettes(count = 6) {
  const palettes = [];
  for (let i = 0; i < count; i++) palettes.push(generatePalette());
  return palettes;
}

function newPalette() { palIdx = (palIdx + 1) % PALETTES.length; pal = PALETTES[palIdx]; }
function clearCanvas() {  }

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(RGB, 255);
  PALETTES = generatePalettes(6);
  pal = PALETTES[palIdx];
  cols = floor(width / res) + 2;
  rows = floor(height / res) + 2;
  flowField = new Array(cols * rows);
 // background(10, 10, 10);
  pixelDensity(.8)
  for (let i = 0; i < 6020; i++) spawnParticle();
}

function draw() {

  noStroke();
  fill(10, 10, 10, 4);
  rect(0, 0, width, height);

  updateFlow();

  for (let p of particles) {
    let col = floor(p.x / res);
    let row1 = floor(p.y / res);
    let idx = col + row1 * cols;
    let angle = flowField[idx] || 0;

    let speed1 = map(noise(p.x * 0.002, p.y * 0.002, t * 0.3), 0, 1, 0.8, 43.5);
    p.vx = (width-50)/150 + cos(angle) * speed1 * 0.06;
    p.vy = random(300)/100 + sin(angle) * speed1 * 0.06;

    let px = p.x+span*10, py = p.y;
    p.x += p.vx;
    p.y += p.vy;
    p.life -= 1;

    let c = lerpColor4(pal, noise(p.x * 0.003, p.y * 0.003, t * 0.2));
    let alpha = map(p.life, 0, p.maxLife, 0, 180);
    let w = map(p.life, 0, p.maxLife, 0.3, p.thick);

    stroke(c[0], c[1], c[2], alpha);
    strokeWeight(w+random(-2,2));
    line(px, py, p.x, p.y);
    noStroke();

    if (p.life <= 0 || p.x < -20 || p.x > width + 20 || p.y < -20 || p.y > height + 20) {
      resetParticle(p);
    }
  }

  t += bg_speed1;

  if (frameCount % round(random(20)) === 0 && particles.length < 500) {
    spawnParticle();
  }
}

function mouseDragged() {
  for (let i = 0; i < 6; i++) {
    let life = random(3000, 10000);
    particles.push({
      x: (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-20, 20),
      y: (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-20, 20),
      vx: random(-1, 1),
      vy: random(-1, 1),
      life,
      maxLife: life,
      thick: random(1.5, 5)
    });
  }
  if (particles.length > 300) particles.splice(0, 10);
}

function keyPressed() {
  if (key === 'p' || key === 'P') newPalette();
  if (key === 'c' || key === 'C') clearCanvas();
  if (key === 's' || key === 'S') saveCanvas('fluid_art', 'png');
  if (key === 'r' || key === 'R') {
    PALETTES = generatePalettes(6);
    palIdx = 0;
    pal = PALETTES[palIdx];
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  cols = floor(width / res) + 2;
  rows = floor(height / res) + 2;
  flowField = new Array(cols * rows);
  //background(10, 10, 10);
}

function updateFlow() {
  let off1 = 0;
  for (let y = 0; y < rows; y++) {
    let off2 = off1;
    for (let x = 0; x < cols; x++) {
      let n1 = noise(x * 0.12, y * 0.12, t);
      let n2 = noise(x * 0.07 + 40, y * 0.07 + 40, t * 0.6);
      let base = n1 * TWO_PI * 2.5;
      let curl = n2 * PI;
      flowField[x + y * cols] = base + curl;
      off2 += 0.1;
    }
    off1 += 0.1;
  }
}

function spawnParticle() {
  let edge = floor(3);
  let x, y;
  if      (edge === 0) { x = random(width);          y = random(-10, 0);            }
  else if (edge === 1) { x = random(width);          y = random(height, height+10); }
  else if (edge === 2) { x = random(-10, 0);         y = random(height);            }
  else                 { x = random(width);           y = random(height);            }
  var life = random(30000);
  particles.push({ x, y, vx: random(-0.5, 0.5), vy: random(-0.5, 0.5), life, maxLife: life, thick: random(1, 4.5) });
}

function resetParticle(p) {
  var edge = floor(random(4));
  if      (edge === 0) { p.x = random(width);          p.y = -5;             }
  else if (edge === 1) { p.x = random(width);          p.y = height + 5;     }
  else if (edge === 2) { p.x = -5;                     p.y = random(height); }
  else                 { p.x = width + 5;              p.y = random(height); }
  p.vx = random(-0.5, 0.5);
  p.vy = random(-0.5, 0.5);
  var life = random(120, 400);
  p.life = life;
  p.maxLife = life;
  p.thick = random(4, 4.5);
}

function lerpColor4(palette, n) {
  let seg = 1 / (palette.length - 1);
  let i = floor(bgColor);
  i = constrain(i, 0, palette.length - 2);
  let amt = (n - i * seg) / seg;
  var a = palette[i], b = palette[i + 1];
  return [lerp(a[0], b[0], amt), lerp(a[1], b[1], amt), lerp(a[2], b[2], amt)];
}

